pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmount, uint256 collectAmount, uint256 minSum) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        vm.assume(collectAmount <= c.balances(address(this)));
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(c.MinSum() == minSum);
    }

    function testFuzz_run(uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        _run(depositAmount, collectAmount, minSum);
    }

    fallback() external payable {}
}
